script:
import assert from 'node:assert/strict';
import {readFile,writeFile} from 'node:fs/promises';
import {JSONParser} from './package/dist/mjs/index.js';
const paths=['$.type','$.uuid','$.timestamp','$.sessionId','$.parentSessionId','$.requestId','$.message.id','$.message.model','$.message.usage'];
const base=JSON.parse((await readFile('/workspace/huihua/fixtures/claude/usage-only.jsonl','utf8')).split('\n')[0]);
const content=JSON.parse((await readFile('/workspace/huihua/fixtures/claude/simple.jsonl','utf8')).trim().split('\n')[1]).message.content;
function selective(line) {
 const output={};const parser=new JSONParser({paths,keepStack:false});
 parser.onValue=({key,value,stack})=>{
  if(stack.length===1)output[key]=value;
  else if(stack.length===2)(output.message??={})[key]=value;
 };
 parser.write(line);if(!parser.isEnded)parser.end();return output;
}
const results=[];
for(const rich of [false,true]){
 const lines=Array.from({length:20000},(_,i)=>JSON.stringify({...base,uuid:`row-${i}`,requestId:`request-${i}`,message:{...base.message,id:`message-${i}`,...(rich?{content:Array.from({length:16}).fill(content[0])}:{})}}));
 for(const line of lines.slice(0,100)){
  const v=JSON.parse(line);assert.deepEqual(selective(line),{type:v.type,uuid:v.uuid,sessionId:v.sessionId,timestamp:v.timestamp,requestId:v.requestId,message:{id:v.message.id,model:v.message.model,usage:v.message.usage}});
 }
 const samples=[];
 for(let r=0;r<8;r++)for(const mode of r%2===0?['native','selective']:['selective','native']){
  let count=0;const start=performance.now();for(const line of lines){const v=mode==='native'?JSON.parse(line):selective(line);count+=v.message.usage.output_tokens;}assert.equal(count,80000);
  if(r!==0)samples.push({mode,ms:performance.now()-start});
 }
 results.push({workload:rich?'content':'usage-only',rows:lines.length,bytes:lines.reduce((sum,line)=>sum+Buffer.byteLength(line)+1,0),samples});
}
await writeFile('/workspace/work/huihua-usage-bench/selective-eval/probe.json',JSON.stringify({node:process.version,library:'@streamparser/json@0.0.26',method:'Decode-only diagnostic probe; selector builds only nine requested paths. One warmup, seven rotated repeats. Not a full-output CLI performance result.',results},null,2));
for(const result of results)for(const mode of ['native','selective'])console.log(result.workload,mode,result.samples.filter(s=>s.mode===mode).map(s=>s.ms).sort((a,b)=>a-b)[3]);
